/**
 * One scratch workspace: an in-memory PGlite running in its own worker thread. PGlite executes
 * synchronously inside WebAssembly and ignores `statement_timeout`, so a runaway statement would
 * block the API's event loop; in a worker the host can enforce the timeout by terminating it.
 *
 * Standalone on purpose: Node loads this file directly (type stripping in development, the
 * bundled `.mjs` in production), so it imports nothing from the workspace packages. Statements
 * arrive already validated and regenerated by the scratch guard.
 */
import { parentPort } from 'node:worker_threads';
import { PGlite } from '@electric-sql/pglite';

type ColumnType = 'text' | 'numeric' | 'timestamp' | 'boolean';

export type WorkerRequest =
  | { id: number; op: 'exec'; sql: string; mutating: boolean; limits: Limits }
  | { id: number; op: 'tables' }
  | {
      id: number;
      op: 'import';
      table: string;
      columns: Array<{ name: string; type: ColumnType }>;
      rows: unknown[][];
      limits: Limits;
    }
  | { id: number; op: 'dryRun'; sql: string; target: string; previewRows: number };

export interface Limits {
  maxRows: number;
  maxTables: number;
  maxResultRows: number;
}

export interface WorkerError {
  code: 'QUERY_LIMIT_EXCEEDED' | 'VALIDATION_ERROR' | 'INTERNAL_ERROR';
  message: string;
  sqlState?: string;
}

export type WorkerResponse =
  | { id: number; ok: true; result: unknown }
  | { id: number; ok: false; error: WorkerError }
  | { ready: true };

interface Rows {
  columns: string[];
  rows: unknown[][];
  truncated: boolean;
}

class LimitError extends Error {}

const SQL_TYPES: Record<ColumnType, string> = {
  text: 'text',
  numeric: 'numeric',
  timestamp: 'timestamp',
  boolean: 'boolean',
};

const db = new PGlite();
let queue: Promise<void> = Promise.resolve();

const port = parentPort;
if (port) {
  port.on('message', (msg: WorkerRequest) => {
    queue = queue.then(() => handle(msg));
  });
  void db.waitReady.then(() => port.postMessage({ ready: true } satisfies WorkerResponse));
}

async function handle(msg: WorkerRequest): Promise<void> {
  let response: WorkerResponse;
  try {
    response = { id: msg.id, ok: true, result: await dispatch(msg) };
  } catch (err) {
    response = { id: msg.id, ok: false, error: toWorkerError(err) };
  }
  port?.postMessage(response);
}

async function dispatch(msg: WorkerRequest): Promise<unknown> {
  switch (msg.op) {
    case 'exec':
      return exec(msg.sql, msg.mutating, msg.limits);
    case 'tables':
      return listTables(true);
    case 'import':
      return importRows(msg.table, msg.columns, msg.rows, msg.limits);
    case 'dryRun':
      return dryRun(msg.sql, msg.target, msg.previewRows);
  }
}

async function exec(sql: string, mutating: boolean, limits: Limits) {
  await db.query('BEGIN');
  try {
    const res = await db.query<unknown[]>(sql, [], { rowMode: 'array' });
    if (mutating) await enforceQuota(limits);
    // Reads never keep side effects (a data-modifying CTE inside a SELECT is undone).
    await db.query(mutating ? 'COMMIT' : 'ROLLBACK');
    const out = shape(res.fields, res.rows, limits.maxResultRows);
    // PGlite reports affectedRows 0 for a read, so a read counts the rows it returned.
    return { ...out, rowCount: mutating ? (res.affectedRows ?? 0) : res.rows.length };
  } catch (err) {
    await rollback();
    throw err;
  }
}

async function importRows(
  table: string,
  columns: Array<{ name: string; type: ColumnType }>,
  rows: unknown[][],
  limits: Limits,
) {
  const defs = columns.map((c) => `${quote(c.name)} ${SQL_TYPES[c.type]}`).join(', ');
  await db.query('BEGIN');
  try {
    await db.query(`DROP TABLE IF EXISTS ${quote(table)}`);
    await db.query(`CREATE TABLE ${quote(table)} (${defs})`);
    if (columns.length > 0) {
      const perBatch = Math.max(1, Math.min(1000, Math.floor(30_000 / columns.length)));
      const names = columns.map((c) => quote(c.name)).join(', ');
      for (let start = 0; start < rows.length; start += perBatch) {
        const batch = rows.slice(start, start + perBatch);
        const params: unknown[] = [];
        const tuples = batch.map((row) => {
          const slots = columns.map((_c, i) => {
            params.push(row[i] ?? null);
            return `$${params.length}`;
          });
          return `(${slots.join(', ')})`;
        });
        await db.query(
          `INSERT INTO ${quote(table)} (${names}) VALUES ${tuples.join(', ')}`,
          params,
        );
      }
    }
    await enforceQuota(limits);
    await db.query('COMMIT');
    return { rows: rows.length };
  } catch (err) {
    await rollback();
    throw err;
  }
}

async function dryRun(sql: string, target: string, previewRows: number) {
  await db.query('BEGIN');
  try {
    const before = await snapshot(target, previewRows);
    const res = await db.query(sql);
    const after = await snapshot(target, previewRows);
    return { before, after, rowCount: res.affectedRows ?? 0 };
  } finally {
    await rollback();
  }
}

async function snapshot(table: string, limit: number): Promise<Rows> {
  const res = await db.query<unknown[]>(`SELECT * FROM ${quote(table)} LIMIT ${limit + 1}`, [], {
    rowMode: 'array',
  });
  return shape(res.fields, res.rows, limit);
}

async function listTables(withCounts: boolean) {
  const res = await db.query<{ schema: string; name: string }>(
    `SELECT n.nspname AS schema, c.relname AS name
       FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.relkind IN ('r', 'p')
        AND n.nspname NOT IN ('pg_catalog', 'information_schema')
        AND n.nspname NOT LIKE 'pg_toast%'
      ORDER BY c.relname`,
  );
  const out: Array<{ name: string; rows: number }> = [];
  for (const t of res.rows) {
    let rows = 0;
    if (withCounts) {
      const c = await db.query<{ n: number }>(
        `SELECT count(*)::int AS n FROM ${quote(t.schema)}.${quote(t.name)}`,
      );
      rows = c.rows[0]?.n ?? 0;
    }
    out.push({ name: t.name, rows });
  }
  return out;
}

async function enforceQuota(limits: Limits) {
  const tables = await listTables(true);
  if (tables.length > limits.maxTables) {
    throw new LimitError(`The workspace is limited to ${limits.maxTables} tables.`);
  }
  const total = tables.reduce((sum, t) => sum + t.rows, 0);
  if (total > limits.maxRows) {
    throw new LimitError(`The workspace is limited to ${limits.maxRows} rows in total.`);
  }
}

async function rollback() {
  try {
    await db.query('ROLLBACK');
  } catch {
    // No transaction open.
  }
}

function shape(fields: Array<{ name: string }>, rows: unknown[][], limit: number): Rows {
  const truncated = rows.length > limit;
  const kept = truncated ? rows.slice(0, limit) : rows;
  return {
    columns: fields.map((f) => f.name),
    rows: kept.map((r) => r.map(plain)),
    truncated,
  };
}

/** Values that survive structured cloning and later JSON serialization. */
function plain(value: unknown): unknown {
  if (typeof value === 'bigint') return value.toString();
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value.toISOString();
  if (value instanceof Uint8Array) return `\\x${Buffer.from(value).toString('hex')}`;
  return value;
}

function quote(identifier: string): string {
  return `"${identifier.replaceAll('"', '""')}"`;
}

function toWorkerError(err: unknown): WorkerError {
  if (err instanceof LimitError) return { code: 'QUERY_LIMIT_EXCEEDED', message: err.message };
  if (err instanceof Error) {
    const sqlState = (err as { code?: unknown }).code;
    if (typeof sqlState === 'string') {
      // A PostgreSQL error about the user's own scratch data.
      return { code: 'VALIDATION_ERROR', message: err.message.slice(0, 500), sqlState };
    }
  }
  return { code: 'INTERNAL_ERROR', message: 'The scratch workspace failed.' };
}
